using DayZ;
using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using UnityEngine;
using UnityEngine.Events;

namespace NativeCode
{
    public enum DEVICE_LEVEL
    {
        HIGH,
        NORMAL,
        LOW
    }

    public class SDKManager : MonoBehaviour
    {
        public static string CONFIG_KEY_APP_ID = "lt_appid";
        public static string CONFIG_KEY_CHANNEL_ID = "lt_channelid";

        public static SDKManager Instance { get; private set; } = null;

        public bool useSDK;

        public UnityEventT2<int, string> eventSDKMsgCallback = new UnityEventT2<int, string>();

        public GameRoot root;

        #region SDKManager的生命周期函数
        /// <summary>
        /// 游戏启动流程：公司SDK->Adjust->SDK管理器->其他SDK->游戏
        /// </summary>
        private void Awake()
        {
            System.Globalization.CultureInfo.CurrentCulture = new System.Globalization.CultureInfo("en");
            EnableETCOn();
            DayZ.ScreenAdaptation.Init();
            BestHTTP.HTTPManager.Setup();
            Instance = this;
            DontDestroyOnLoad(this.gameObject);
            root.LauchGame();
            this.SDKBehavior.Init();
            DayZ.NPEnterGameEventController.SendEvent(DayZ.EnterGameEvent.LTSDKInitOK);
#if EMPIRE
            PlayInstallReferrerManager.Instance.CheckInstall();
#endif

#if RED_ALERT_VI
            //init VIPaymentController
            var v = VIPaymentController.Instance;
#endif
            //this.InitPlugins();
            //DayZ.NPEnterGameEventController.SendEvent(DayZ.EnterGameEvent.SDKInitOK);
            //root.StartGame();
        }

        private void Start()
        {
            this.GatewayCheck();
            DayZ.NPEnterGameEventController.SendEvent(DayZ.EnterGameEvent.GatewayCheck);

        }


        private void GatewayHeartStart()
        {
            new Thread(HeartThreadFunc)
                    .Start();
        }
        void HeartThreadFunc(object param)
        {
            while(true)
            {
                Thread.Sleep(60000);
                try
                {
                    Loom.QueueOnMainThread(() => CoroutineManager.Instance.StartCoroutine(GatewaySystemManager.Instance.SendHeartInfoCoroutine(null)));
                }
                catch(Exception ex)
                {
                    LogCommon.LogException(ex, "HeartThreadFunc");
                }
            }
        }

        private void GatewayCheck()
        {
            GatewaySystemManager.Instance.VersionCheckRequest((bool isSuccess) =>
            {
                if(isSuccess)
                {
                    var heartInfo = GatewaySystemManager.Instance.heartInfo;
                    if (heartInfo != null)
                    {
                        bool v = heartInfo.IsInvalid();
                        bool u = heartInfo.IsNeedForceUpdate();
                        if (v || u)
                        {
                            var versionInfo = heartInfo.data;
                            if(versionInfo != null)
                            {
                                var mainUrl = versionInfo.url;
                                var webUrl = versionInfo.sub_url;
                                var joy = CCCommonUtils.getStringWithEncBySharedUser(Global.JOY_ACCOUNT_ID);
                                if (!string.IsNullOrEmpty(joy))
                                {
                                    DoShowForceUpdateView(mainUrl, v);
                                }
                                else
                                {
                                    if (string.IsNullOrEmpty(webUrl))
                                    {
                                        DoShowForceUpdateView(mainUrl, v);
                                    }
                                    else
                                    {
                                        DoShowForceUpdateView(webUrl, v);
                                    }

                                }
                                return;
                            }
                        }


                    }
                }

                DoNormalInit();
            });
        }

        private void DoShowForceUpdateView(string url, bool invalidTip)
        {
            DoUpdateInit(() =>
            {
                ResInitLoadingViewController.NeedUpdateBag(url, invalidTip);
            });
        }
        private void DoNormalInit()
        {
            var bgcamera = GameObject.FindObjectOfType<BGCamera>();
            bgcamera?.SetLoadingEnable(false);
            StartGatewayHeart();
            this.InitPlugins();
            DayZ.NPEnterGameEventController.SendEvent(DayZ.EnterGameEvent.SDKInitOK);
            root.StartGame(false);

        }

        private void DoUpdateInit(Action callBack)
        {
            StartGatewayHeart();
            this.InitPlugins(true);
            DayZ.NPEnterGameEventController.SendEvent(DayZ.EnterGameEvent.SDKInitOK);
            root.StartGame(true, callBack);
        }

        private void StartGatewayHeart()
        {
            this.GatewayHeartStart();
            DayZ.NPEnterGameEventController.SendEvent(DayZ.EnterGameEvent.GatewayHeart);
        }

        private void EnableETCOn()
        {
            if (Application.platform == RuntimePlatform.WindowsEditor
                || Application.platform == RuntimePlatform.WindowsPlayer
                || Application.platform == RuntimePlatform.Android)
            {
                Shader.EnableKeyword("ETC_ON");
            }
            else
            {
                Shader.EnableKeyword("ETC_OFF");
            }
        }

        private void OnApplicationPause(bool pause)
        {
            this.PluginsPause(pause);
        }

        private void OnApplicationQuit()
        {
            this.PluginsQuit();
        }
        #endregion

        public void SDKInitCallback(string message)
        {
            LogCommon.Log("SDKInitCallback " + message);

            Dictionary<string, object> dict = null;
            int code = GetJsonCode(message, out dict);

            InvokeEventSDKMsgCallback(code, message);

            this.SDKBehavior.Dispatch(code, dict);


        }

        private int GetJsonCode(string result, out Dictionary<string, object> dic)
        {
            dic = MiniJSON.Json.Deserialize(result) as Dictionary<string, object>;
            return dic != null && dic.ContainsKey("code") ? Convert.ToInt32(dic["code"]) : -1;
        }


        #region SDK提供给外部调用的接口
        public void extension(string action, string json) { this.SDKBehavior.extension(action, json); }

        public static string getConfig(string name, string defval)
        {
#if UNITY_EDITOR || UNITY_STANDALONE
            var lines = System.IO.File.ReadAllLines(System.IO.Path.Combine(Application.dataPath, "Plugins/Android/res.androidlib/assets/ltsdk_res/config.txt"));
            foreach (var item in lines)
            {
                if (string.IsNullOrEmpty(item))
                    continue;

                var line = item.Trim();
                if (line.StartsWith(name))
                    return line.Substring(name.Length + 1);
            }
            return defval;
#elif UNITY_ANDROID
            return OnlineSDKManager.instance.onlineSDK.getConfig(name, defval);
#else
