        public ICCManager HelpShiftMgr { get; set; }
        public FirebaseManager FirebaseMgr { get; private set; }
        public FacebookManager FacebookMgr { get; private set; }
        public SignWithApppleManager SignWithApppleMgr { get; private set; }

        public AudienceNetworkAdsManager AudienceNetworkAdsManager { get; private set; }

        public AppReviewManager AppReviewManager { get; private set; }

        /// <summary>
        /// 初始化所有的第三方SDK对象
        /// 在SDKManager的Start中被调用（在Start中调用的原因是因为OnlineManager在Awake要初始化一些信息，为避免执行顺序问题）
        /// </summary>
        private void InitPlugins(bool simple = false)
        {

            this.HelpShiftMgr = GetICCMethod();
            this.plugins.Add(this.HelpShiftMgr);
            if (!simple)
            {
                this.FirebaseMgr = new FirebaseManager();
                this.FacebookMgr = new FacebookManager();
                this.SignWithApppleMgr = new SignWithApppleManager();
                this.AudienceNetworkAdsManager = new AudienceNetworkAdsManager();
                this.AppReviewManager = new AppReviewManager();
                this.plugins.Add(this.FirebaseMgr);
                this.plugins.Add(this.FacebookMgr);
                this.plugins.Add(this.SignWithApppleMgr);
                this.plugins.Add(this.AudienceNetworkAdsManager);
                this.plugins.Add(this.AppReviewManager);
            }

            this.plugins.ForEach(p => p.Install());
        }

        private void Update()
        {
            this.plugins.ForEach(p => p.Tick());
        }

