        private ISDKBehavior SDKBehavior
        {
            get
            {
                if (_currentSDKBehavior == null)
                {
                    _currentSDKBehavior = this.GetSDKBehavior();
                    DayZ.GlobalData.LEVEL = _currentSDKBehavior.getDeviceLevel();
                }
                return _currentSDKBehavior;
            }
        }

        private ISDKBehavior SubSDKBehavior
        {
            get
            {
                if (_subSDKBehavior == null)
                {
                    _subSDKBehavior = this.GetSubSDKBehavior();
                }
                return _subSDKBehavior;
            }
        }

        private ISDKBehavior GetSDKBehavior()
        {
#if ROE_DEV
            if (this.useSDK)
#endif
            {
#if (UNITY_EDITOR || UNITY_STANDALONE) && ROE_DEV
                return new WindowsSDKBehavior();
#elif UNITY_ANDROID
//#if UNITY_ANDROID

#if RED_ALERT_GF
