#endif

                return new AndroidSDKBehavior();
#elif UNITY_IOS
                return new iOSSDKBehavior();
#endif
            }

#if ROE_DEV
            return new EditorSDKBehavior();
#endif
        }

        private ISDKBehavior GetSubSDKBehavior()
        {
#if RED_ALERT_VI
            return new VISDKBehavior();
#endif
            return null;
        }

#endregion

