using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;

namespace NativeCode
{
    public class WindowsSDKBehavior : AbstractSDKBehavior
    {
        private readonly string GSPAY_KEY    = "GSPayKey";
        private readonly string GSPAY_DOMAIN = "GSPayDomain";
        public override void extension(string action, string json)
        {
            Debug.Log($"WindowsSDKBehavior  extension {action} {json}");
        }

        public override void hideToolbar()
        {
            Debug.Log($"WindowsSDKBehavior  hideToolbar");
        }

        public override void login()
        {
            Debug.LogError("EditorSDKBehavior login NotImplementedException");
        }

        public override void logout()
        {
            Debug.Log($"WindowsSDKBehavior  logout");
        }

        public override void pay(GameInfo gameInfo)
        {
            string payUrl = CreateReqParams(gameInfo);
            Debug.Log("WindowsSDKBehavior payUrl: " + payUrl);

            WWW www = new WWW(payUrl);
            Application.OpenURL(www.url);
        }

        public override void setCommon(GameInfo gameInfo)
        {
            Debug.Log($"WindowsSDKBehavior  setCommon");
        }

        public override void showToolbar()
        {
            Debug.Log($"WindowsSDKBehavior  showToolbar");
        }

        public override void switchAccount()
        {
            Debug.Log($"WindowsSDKBehavior  showToolbar");
        }

        public override void setTest(string product_url, string order_url, string notify_url, string query_url)
        {
            Debug.Log($"WindowsSDKBehavior  setTest");
        }

        public override string getCountry()
        {
            return RegionInfo.CurrentRegion.ToString();
        }

        public override string getLanguage()
        {
            return Application.systemLanguage.ToString();
        }

        public override string getAppVersion()
        {
            return Application.version;
        }

        public override string getChannelID()
        {
            return "0000000";
        }


        private string CreateReqParams(GameInfo info)
        {
            string gsPayKey     = SDKManager.getConfig(GSPAY_KEY, string.Empty);
            string gsPayDomain  = SDKManager.getConfig(GSPAY_DOMAIN, string.Empty);

            Dictionary<string, string> aesParamDic = new Dictionary<string, string>();

            Dictionary<string, string> paramDic = new Dictionary<string, string>();

            string appId = info.LtAppId;
            aesParamDic.Add("appId", appId);

            paramDic.Add("packageName", SDKManager.GetPackageName());

            string channelID = getChannelID();
            paramDic.Add("channelID", channelID);

            string userid = info.LtJoyId;
            paramDic.Add("userid", info.LtJoyId);

            string instantid = info.LtInstantId;
            paramDic.Add("instantid", instantid);

            string productId = info.ProductId;
            paramDic.Add("productId", productId);

            string chargeId = info.chargeId;
            paramDic.Add("chargeId",chargeId);

            string productPrice = info.ProductPrice;
            paramDic.Add("productPrice", productPrice);

            string productName = info.ProductName;
            paramDic.Add("productName", productName);

            string gameUid = info.RoleId;
            paramDic.Add("gameUid",gameUid);

            string selfOrderId = info.gameOrderId;
            paramDic.Add("selfOrderId", selfOrderId);

            string reserve = info.LtReserve;
            paramDic.Add("reserve", reserve);

            string jsonParam = LitJson.JsonMapper.ToJson(paramDic);

            //30b74d506480a3308a770c29dbdd247e
            string password = gsPayKey;
            Debug.Log("Encrypt: aesParam: " + jsonParam + "password: " + password);


            // Create sha256 hash
            SHA256 mySHA256 = SHA256Managed.Create();
            byte[] key = mySHA256.ComputeHash(Encoding.ASCII.GetBytes(password));

            // Create secret IV
            byte[] iv = new byte[16];
            for (int i = 0; i < iv.Length; i++)
            {
                iv[i] = (byte)UnityEngine.Random.Range(0, 10);
            }

            byte[] eData = EncryptBytes(jsonParam, key, iv);
            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(iv, 0, iv.Length);
            memoryStream.Write(eData, 0, eData.Length);
            memoryStream.Flush();
            byte[] totalDatas = memoryStream.ToArray();
            memoryStream.Close();
            string base64 = Convert.ToBase64String(totalDatas, 0, totalDatas.Length);
            string c = UrlEncode(base64);
            Debug.Log("c: " + c);
            //string o = DecryptString(c, key, iv);

            aesParamDic.Add("c", c);

            string param = "";
            var pEtr = aesParamDic.GetEnumerator();
            while (pEtr.MoveNext())
            {
                string p = "";
                if (string.IsNullOrEmpty(param))
                {
                    p = string.Format("{0}={1}", pEtr.Current.Key, pEtr.Current.Value);
                }
                else
                {
                    p = string.Format("&{0}={1}", pEtr.Current.Key, pEtr.Current.Value);
                }
                param += p;
            }

            string domainUrl  = gsPayDomain;//"https://netuserqg.warworldgames.com/joystore/index/supportPlat";
            string requestUrl = string.Format("{0}?{1}", domainUrl, param);
            return requestUrl;

        }


        public static byte[] EncryptBytes(string plainText, byte[] key, byte[] iv)
        {
            // Instantiate a new Aes object to perform string symmetric encryption
            Aes encryptor = Aes.Create();

            encryptor.Mode = CipherMode.CBC;
            //encryptor.KeySize = 256;
            //encryptor.BlockSize = 128;
            //encryptor.Padding = PaddingMode.Zeros;

            // Set key and IV
            encryptor.Key = key;
            encryptor.IV = iv;

            // Instantiate a new MemoryStream object to contain the encrypted bytes
            MemoryStream memoryStream = new MemoryStream();

            // Instantiate a new encryptor from our Aes object
            ICryptoTransform aesEncryptor = encryptor.CreateEncryptor();

            // Instantiate a new CryptoStream object to process the data and write it to the 
            // memory stream
            CryptoStream cryptoStream = new CryptoStream(memoryStream, aesEncryptor, CryptoStreamMode.Write);

            // Convert the plainText string into a byte array
            byte[] plainBytes = Encoding.ASCII.GetBytes(plainText);

            // Encrypt the input plaintext string
            cryptoStream.Write(plainBytes, 0, plainBytes.Length);

            // Complete the encryption process
            cryptoStream.FlushFinalBlock();

            // Convert the encrypted data from a MemoryStream to a byte array
            byte[] cipherBytes = memoryStream.ToArray();

            // Close both the MemoryStream and the CryptoStream
            memoryStream.Close();
            cryptoStream.Close();

            // Convert the encrypted byte array to a base64 encoded string
            //string cipherText = Convert.ToBase64String(cipherBytes, 0, cipherBytes.Length);

            // Return the encrypted data as a string
            return cipherBytes;
        }

        public static string DecryptString(string cipherText, byte[] key, byte[] iv)
        {
            // Instantiate a new Aes object to perform string symmetric encryption
            Aes encryptor = Aes.Create();

            encryptor.Mode = CipherMode.CBC;
            //encryptor.KeySize = 256;
            //encryptor.BlockSize = 128;
            //encryptor.Padding = PaddingMode.Zeros;

            // Set key and IV
            encryptor.Key = key;
            encryptor.IV = iv;

            // Instantiate a new MemoryStream object to contain the encrypted bytes
            MemoryStream memoryStream = new MemoryStream();

            // Instantiate a new encryptor from our Aes object
            ICryptoTransform aesDecryptor = encryptor.CreateDecryptor();

            // Instantiate a new CryptoStream object to process the data and write it to the 
            // memory stream
            CryptoStream cryptoStream = new CryptoStream(memoryStream, aesDecryptor, CryptoStreamMode.Write);

            // Will contain decrypted plaintext
            string plainText = String.Empty;

            try
            {
                // Convert the ciphertext string into a byte array
                byte[] cipherBytes = Convert.FromBase64String(cipherText);

                // Decrypt the input ciphertext string
                cryptoStream.Write(cipherBytes, 0, cipherBytes.Length);

                // Complete the decryption process
                cryptoStream.FlushFinalBlock();

                // Convert the decrypted data from a MemoryStream to a byte array
                byte[] plainBytes = memoryStream.ToArray();

                // Convert the decrypted byte array to string
                plainText = Encoding.ASCII.GetString(plainBytes, 0, plainBytes.Length);
            }
            finally
            {
                // Close both the MemoryStream and the CryptoStream
                memoryStream.Close();
                cryptoStream.Close();
            }

            // Return the decrypted data as a string
            return plainText;
        }

        public static string UrlEncode(string value)
        {
            System.Text.StringBuilder builder = new System.Text.StringBuilder();
            byte[] bytes = System.Text.Encoding.UTF8.GetBytes(value); //默认是System.Text.Encoding.Default.GetBytes(str)
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(@"%" + System.Convert.ToString(bytes[i], 16));
            }
            return builder.ToString();
        }

