   346→        private IEnumerator StartCountDownTime()
   347→        {
   348→            while (GameState == GameStateType.StartGameAni || GameState == GameStateType.WaitFirstStartGame)
   349→            {
   350→                yield return null;
   351→            }
   352→            while (countDownElaspe > 0)
   353→            {
   354→                yield return null;
   355→                countDownElaspe -= Time.deltaTime;
