using System;
using System.Collections;
using System.Collections.Generic;
using RVOV2;
using UnityEngine;
using UnityEngine.Events;
using Vector2 = UnityEngine.Vector2;
#if RED_ALERT
using UnityEngine.Rendering.PostProcessing;
#endif
namespace DayZ.LastWar
{
    public enum EFighting
    {
        None,
        PowerCrushing,      //战力碾压
        Equal,              //战力相等
        Insufficient,       //战力不足
    }
    public class GameManager : SingletonMono<GameManager>
    {
        public enum GameStateType //关卡状态
        {
            None,
            StartGameAni,           //第一关开始游戏动画
            WaitFirstStartGame,     //等待第一关点击开始游戏
            ChooseHero,             //选择英雄状态
            OpeningShow,            //播放开场动画
            GameRunning,            //游戏正常运行
            GamePause,              //游戏暂停
            GameOver,               //游戏结束
        }
        [SerializeField] private GameStateType gameState;
        public GameStateType GameState => gameState;
        public Material skyboxMaterial;
        public Transform PlayerRoot;
        private Vector3 startPos;
        public Vector3 StartPos { get => startPos; }
        public Transform ArmyRoot { get; set; }
        public Lastwar_scene LevelConfig { get; set; }

        private int result = -1;
        public bool Success { get { if (result == 0) return true; else return false; } }
        private float playerMoveElapse = 0;     //成功后玩家向前方奔跑计时器
        private float playerMoveTime = 4f;
        private float showGameOverTipTime = 0.5f; //弹出结算提示
        private UnityAction<UnityAction> startMonster;
        public Dictionary<int, PVEHero> BestListDict = new Dictionary<int, PVEHero>();
        public EFighting eFighting;
        public bool isTriggerWarning;           //是否进入警告区域
        public bool isInBossArea;               //是否进入boss战斗区域
        [HideInInspector] public LastWarMainView mainView;        //主菜单UI

        public float bossAttackRadius = 10f;    //自由boss战场地大小半径
        public Transform bossCenter;            //自由boss战斗场地中心
        public bool isStartFreeBoss =>          //是否正在打自由boss战斗
            LevelManager.Instance.levelTypeMode == ELevelType.FreeBoss && isInBossArea;
        public Transform deadArea;
#if RED_ALERT
        public PostProcessVolume PostProcessVolume;
        public PostProcessLayer PostProcessLayer;
#endif
        public List<Light> lights = new List<Light>();
        private Light[] allLight;
        public DamageNumberRender normalNumberObject;
        public DamageNumberRender critNumberObject;
        public DamageNumberRender heroNumberObject;
        public DamageNumberRender flyNumberObject;
        //多伤害显示管理
        public DamageNumberManager damageNumberManager;

        [HideInInspector] public MonsterInArea monsterInArea;

        public GameObject obstacle;                 //障碍物
        public GameObject mainCM;

        public int killTotalNums = 0;               //击杀数
        public float startTime { get; private set; } = 0f;
        public float runningTime { get; private set; } = 0f;              //通关时间

        public readonly float CountDown = 4f;
        private float countDownElaspe = 0;
        public float CountDownElaspe => countDownElaspe;
        public bool countDownOver = false;
        public UnityEvent countDownOverEvent = new UnityEvent();
        /// <summary>
        /// 红警要求的特殊需求，所有伤害数字显示上/10
        /// </summary>
        [HideInInspector] public readonly int redDamageShow = 10;

        private Coroutine startMotionCoroutine = null;
        public void SetGameState(GameStateType gameState)
        {
            this.gameState = gameState;
        }
        protected override void Awake()
        {
            base.Awake();
            startPos = PlayerRoot.transform.position;
            if (deadArea == null)
                deadArea = PlayerRoot.transform.Find("shadai2");
            allLight = GameObject.FindObjectsOfType<Light>();
            foreach (var light in allLight)
            {
                if (!GameManager.Instance.lights.Contains(light))
                    light.enabled = false;
            }

            this.gameObject.AddComponent<PPManager>();

            SetupRVOConfig();
            countDownElaspe = CountDown;

        }

        void SetupRVOConfig()
        {
            if (CCCommonUtils.IsRedAlert() == false)
            {
                return;
            }
            Simulator.Instance.setTimeStep(0.1f);
            Simulator.Instance.setAgentDefaults(1f, 10, 5.0f, 5.0f, 0.3f, 100.0f, new RVOV2.Vector2(0.0f, 0.0f));
            //StartCoroutine(InitThreadCount());
            // add in awake
            Monster.m_agentMap.Clear();
            Simulator.Instance.processObstacles();
            //gameObject.AddComponent<LazyInstanceManager>();
        }

        void InitThreadCount()
        {
            if (CCCommonUtils.IsRedAlert() == false)
            {
                return;
            }
            //yield return new WaitForSeconds(2f);
            Simulator.Instance.SetNumWorkers(50);
            Simulator.Instance.Start = true;
        }

        private void OnApplicationQuit()
        {
            LogCommon.LogError("清除子线程，防止编辑器卡死");
            Simulator.Instance.Start = false;
        }

        public void ImmediateOnDestroy()
        {
            if (CCCommonUtils.IsRedAlert() == false)
            {
                return;
            }
            //通知子线程自动退出释放
            Simulator.Instance.Start = false;
            Simulator.Instance.Clear();
            LogCommon.LogError("解散子线程");
        }

        public bool UseHitEffect = true;
        // #if ROE_DEV
#if ROE_DEV
        bool isShow = false;
        private void OnGUI()
        {
            // if (!isShow)
            // return;
            if (GUI.Button(new Rect(300, 0, 100, 100), "直接获胜"))
            {
                gameState = GameStateType.GameOver;
                Scheduler.Instance.scheduleOnce((f) =>
                {
                    Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_GameOver, 0);
                }, 0.1f, this);
            }

            if (GUI.Button(new Rect(Screen.width - 100, 0, 80, 80), "开关等待" + Simulator.Instance.WaitThread))
            {
                Simulator.Instance.WaitThread = !Simulator.Instance.WaitThread;
            }

            if (GUI.Button(new Rect(Screen.width - 100, 100, 80, 80), "hit特效" + UseHitEffect))
            {
                UseHitEffect = !UseHitEffect;
            }
            if (GUI.Button(new Rect(Screen.width - 100, 200, 80, 80), "帧数" + targetRate))
            {
                targetRate = targetRate == 200 ? 30 : 200;
                Application.targetFrameRate = targetRate;
            }


            GUI.Label(new Rect(Screen.width - 100, 200, 80, 80), "线程数" + Simulator.Instance.requiredWorkers);
            GUI.Label(new Rect(Screen.width - 100, 300, 120, 80), "canAddAgent" + Simulator.Instance.CanAddMoreAgent);

        }
#endif
        void TickRVOTask()
        {
            if (CCCommonUtils.IsRedAlert())
            {
                RVOV2.Simulator.Instance.doStep(Time.deltaTime);
            }
        }

        public void SetStartTime()
        {
            startTime = Time.time;
        }

        private int targetRate = 30;
        private void Update()
        {
#if ROE_DEV
            if (Input.GetKeyDown(KeyCode.S))
                isShow = !isShow;
#endif
            //只有红警需要
            TickRVOTask();
            if (Success)
            {
                if (playerMoveElapse <= playerMoveTime)
                {
                    PlayerManager.Instance.MoveHerosSuccess();
                    playerMoveElapse += Time.deltaTime;
                }
            }

            if (GameState == GameStateType.GameRunning)
            {
                runningTime = Time.time - startTime;
            }

            SkipGame();
            CheckRunGameOver(null);
            CheckRunBossGameOver(null);
            CheckFreeBossGameOver(null);
        }

        private void InitData(Lastwar_scene config)
        {
            LevelManager.Instance.ReadData(config);
            LevelConfig = config;
            playerMoveElapse = 0f;
            PlayerRoot.transform.position = startPos;
            bossAttackRadius = 8f;
            countDownOver = false;
        }

        private void InitScene()
        {
            CreateRoot();
            GridManager.Instance.playerStart = LastWarScene.Instance.SceneObj.transform.Find("PlayerBirth");
            monsterInArea = PlayerRoot.GetComponent<MonsterInArea>();
            GridManager.Instance.Init(GridManager.Instance.playerStart);
            if (LevelManager.instance.herolevelType == ELevelType.Hero)
                GridManager.Instance.ShowGrid(true);
            else
                GridManager.Instance.ShowGrid(false);
        }

        /// <summary>
        /// 初始化游戏
        /// </summary>
        /// <param name="config"></param>
        public void InitGame(Lastwar_scene config)
        {
            Global.addNotifyObserver(this, CheckGuardGameOver, LastWarHelper.LASTWAR_MSG_CheckGameOver);
            InitData(config);
            InitScene();
            CameraMove.instance.InitCM();
            PlayerManager.Instance.Init();
            MonsterManager.instance.Init(InitThreadCount);

            if (normalNumberObject != null && critNumberObject != null && flyNumberObject != null && heroNumberObject != null)
            {
                damageNumberManager = new DamageNumberManager(
                    normalNumberObject.gameObject,
                    critNumberObject.gameObject,
                    flyNumberObject.gameObject,
                    heroNumberObject.gameObject,
                    null,
                    Vector3.one * -1000);
                //damageNumberManager.SetCMTran(mainCM.transform);
            }
            damageNumberManager?.PreLoadDamageNums(MonsterManager.instance.GetMonsterPreLoad() * 4);
        }




        /// <summary>
        /// 开始战斗
        /// </summary>
        public void StartBattle(UnityAction unityAction)
        {
            UpdateEFighting();
            MonsterManager.instance.ShowMonster();
            unityAction?.Invoke();
            //startMonster.Invoke(unityAction);
            //startMonster = null;
            if (LevelManager.instance.herolevelType == ELevelType.Soldier)
                CameraMove.instance.PlaySoliderAni();
            else
            {
                CameraMove.Instance.PlayHeroAni();
            }

            SetStartTime();
            StartCoroutine(StartCountDownTime());
            GridManager.Instance.ShowGrid(false);
            PlayerManager.instance.RemoveWarPlaneInGrid();
            PlayerManager.Instance.SetStartAllHeroPos();
            PlayerManager.instance.AddWarplaneData2Hero();
            PlayerManager.instance.SetPlayerCanBeFind();
            var manager = DayZ.Container.Instance.Get<ILastWarManager>();
            PVEController.Instance.SendEnterMiniGame(manager.GameData.Id, manager.GameType);
        }


        public void StartShowMotion()
        {
            if (!CCCommonUtils.IsRedAlert())
                return;
            if (LevelManager.Instance.levelTypeMode == ELevelType.Guard ||
                LevelManager.Instance.levelTypeMode == ELevelType.GuardBoss ||
                LevelManager.Instance.levelTypeMode == ELevelType.FreeBoss)
            {
                if (startMotionCoroutine == null)
                    startMotionCoroutine = StartCoroutine(IEShowMotion());
            }

        }

        private void SetTimeScale(float time)
        {
            Time.timeScale = time;
        }
        private IEnumerator IEShowMotion()
        {
            SetTimeScale(0.2f);
            yield return new WaitForSecondsRealtime(3f);
            SetTimeScale(1);
        }

        private IEnumerator StartCountDownTime()
        {
            while (GameState == GameStateType.StartGameAni || GameState == GameStateType.WaitFirstStartGame)
            {
                yield return null;
            }
            while (countDownElaspe > 0)
            {
                yield return null;
                countDownElaspe -= Time.deltaTime;
            }
            countDownOver = true;
            countDownOverEvent?.Invoke();
