        private void CheckGuardGameOver(object o)
        {
            CheckGuardBossGameOver(o);
            if (LevelManager.Instance.levelTypeMode != ELevelType.Guard)
                return;
            if (GameManager.Instance.GameState != GameManager.GameStateType.GameRunning)
                return;
            result = -1;
            if (MonsterManager.instance.attackMonsters.FinalCount == 0)
                result = 0;
            if (PlayerManager.instance.AllHeroDead())
                result = 1;
            if (result > -1)
            {
                SetGameState(GameStateType.GameOver);
                //isGameOver = true;
                if (result == 1)
