        private void CheckRunGameOver(object o)
        {
            if (LevelManager.Instance.levelTypeMode != ELevelType.Run)
                return;
            if (GameManager.Instance.GameState != GameManager.GameStateType.GameRunning)
                return;
            result = -1;
            Vector3 offset = PlayerRoot.transform.position - startPos;
