            if (dis >= LevelConfig.distance)
                result = 0;

            if (PlayerManager.instance.AllHeroDead())
                result = 1;

            if (result > -1)
            {
                //isGameOver = true;
                SetGameState(GameStateType.GameOver);
                if (result == 1)
                {
                    Scheduler.Instance.scheduleOnce((f) =>
                    {
                        Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_GameOver, result);
                    }, 0.1f, this);
                }
                else if (result == 0)       //胜利
                {
                    Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_SUCCESS_Run);
                    List<Monster> monsters = MonsterManager.instance.attackMonsters.Items;
                    for (int i = monsters.Count - 1; i >= 0; i--)
                    {
                        monsters[i].SetState(BehaviorState.Dead);

                    }
                    Scheduler.Instance.scheduleOnce((f) =>
                    {
                        Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_GameOver, result);
                    }, showGameOverTipTime, this);
                }
            }
