        /// <summary>
        /// 战力检查
        /// </summary>
        public EFighting CheckAtk()
        {
            PVEJoinerInfo atker = PVEController.Instance.GetPveAttackInfo(BestListDict.Values);
            double curr_power = 0;
            if (atker == null)
                LogCommon.LogError("没有收到攻击方战力信息");
            else
            {
                curr_power += atker.power;
                if (PlayerManager.Instance.currentuav != null)
                    curr_power += PlayerManager.Instance.currentuav.GetTotalPower();
            }

            var manager = DayZ.Container.Instance.Get<ILastWarManager>();
            PVEJoinerInfo defer = PVEController.Instance.GetPveDefenserInfo(manager.GameData);  //monsterid //
            if (defer == null)
                LogCommon.LogError("没有收到防守方战力信息");
            return CheckAtkAlgorithm((float)curr_power, (float)defer.power);
        }

        /// <summary>
        /// 战力检测算法
        /// </summary>
        /// <returns></returns>
        public EFighting CheckAtkAlgorithm(float atker, float defer)
        {
            float percent = atker / defer;
            if (percent >= LastWarHelper.LASTWAR_Property_Power_Rate1)
                return EFighting.PowerCrushing;
            else if (percent < LastWarHelper.LASTWAR_Property_Power_Rate1 && percent >= LastWarHelper.LASTWAR_Property_Power_Rate2)
                return EFighting.Equal;
            else
                return EFighting.Insufficient;
        }

        public void UpdateEFighting()
        {
            eFighting = GameManager.Instance.CheckAtk();
        }

        public void SkipGame()
        {
#if ROE_DEV
            if (LevelConfig.Skip == 1)  //表示可以跳过
            {
                if (Input.GetKeyDown(KeyCode.Backspace))
                {
                    SetGameState(GameStateType.GameOver);
                    //isGameOver = true;
                    Scheduler.Instance.scheduleOnce((f) =>
                    {
                        Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_GameOver, 0);
                    }, 0.1f, this);
                }
                if (Input.GetKeyDown(KeyCode.F2))
                {
                    SetGameState(GameStateType.GameOver);
                    //isGameOver = true;
                    Scheduler.Instance.scheduleOnce((f) =>
                    {
                        Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_GameOver, 1);
                    }, 0.1f, this);
                }
            }
#endif
        }
        public void ClearAll()
        {
            SetTimeScale(1);
            Global.removeNotifyObserver(this, LastWarHelper.LASTWAR_MSG_CheckGameOver);
            Global.POST_SAFE_NOTIFY(LastWarHelper.LASTWAR_MSG_CLEARALL);
            StopAllCoroutines();
            Scheduler.Instance.unschedule(this);
            MonsterManager.instance.Clear();
            PlayerManager.instance.Clear();
            NoDisableMonoManager.instance.Clear();
            QuadTreeManager.Instance.Clear();
            GameObjectPools.instance.DestroyAll();
            allLight = GameObject.FindObjectsOfType<Light>();
            foreach (var light in allLight)
            {
                light.enabled = true;
            }
            countDownOverEvent.RemoveAllListeners();
            Destroy(ArmyRoot.gameObject);
            damageNumberManager?.Clear();
            instance = null;
            Debug.LogError("GameManager Clear All");
            ImmediateOnDestroy();
        }
    }
